// Analytics Pipeline for Product Events
import { IngestPipeline } from "@514labs/moose-lib";

// Data model matching the JSON event structure
export interface ProductEvent {
  eventId: string;
  eventTs: Date;
  userId: string;
  productId: string;
  eventType: string;  // 'view', 'cart', 'purchase'
  properties: {
    page?: string;      // for view events
    price?: number;     // for purchase events
  };
}

// Ingest pipeline - creates table, stream, and REST API endpoint
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["eventType", "eventTs", "userId"] // optimize for analytics queries
  },
  stream: true,
  ingestApi: true,
});

import { MaterializedView } from "@514labs/moose-lib";
import { ProductEvent } from "../index";

// Materialized view for top products analytics
export interface TopProductMetrics {
  productId: string;
  viewCount: number;
  cartCount: number;
  purchaseCount: number;
  totalRevenue: number;
  lastUpdated: Date;
}

export const TopProductsView = new MaterializedView<TopProductMetrics>("TopProductMetrics", {
  source: "ProductEvent",
  sql: `
    SELECT
      productId,
      countIf(eventType = 'view') as viewCount,
      countIf(eventType = 'cart') as cartCount,
      countIf(eventType = 'purchase') as purchaseCount,
      sumIf(JSONExtractFloat(properties, 'price'), eventType = 'purchase') as totalRevenue,
      now() as lastUpdated
    FROM currentDatabase().ProductEvent_0_0
    GROUP BY productId
  `,
  orderByFields: ["totalRevenue", "purchaseCount"],
});

import { MaterializedView } from "@514labs/moose-lib";
import { ProductEvent } from "../index";

// Conversion funnel metrics tracking unique users through the journey
export interface ConversionFunnelMetrics {
  step: string;
  uniqueUsers: number;
  totalEvents: number;
  lastUpdated: Date;
}

export const ConversionFunnelView = new MaterializedView<ConversionFunnelMetrics>("ConversionFunnelMetrics", {
  source: "ProductEvent",
  sql: `
    SELECT
      eventType as step,
      uniqExact(userId) as uniqueUsers,
      count() as totalEvents,
      now() as lastUpdated
    FROM currentDatabase().ProductEvent_0_0
    WHERE eventType IN ('view', 'cart', 'purchase')
    GROUP BY eventType
    ORDER BY
      CASE eventType
        WHEN 'view' THEN 1
        WHEN 'cart' THEN 2
        WHEN 'purchase' THEN 3
        ELSE 4
      END
  `,
  orderByFields: ["step"],
});

import { MaterializedView } from "@514labs/moose-lib";
import { ProductEvent } from "../index";

// Hourly activity metrics tracking events per hour
export interface HourlyActivityMetrics {
  hour: Date;
  eventType: string;
  eventCount: number;
  uniqueUsers: number;
  lastUpdated: Date;
}

export const HourlyActivityView = new MaterializedView<HourlyActivityMetrics>("HourlyActivityMetrics", {
  source: "ProductEvent",
  sql: `
    SELECT
      toStartOfHour(eventTs) as hour,
      eventType,
      count() as eventCount,
      uniqExact(userId) as uniqueUsers,
      now() as lastUpdated
    FROM currentDatabase().ProductEvent_0_0
    GROUP BY hour, eventType
    ORDER BY hour DESC, eventType
  `,
  orderByFields: ["hour", "eventType"],
});

