const http = require('http');
const { exec } = require('child_process');

const PORT = 4000;

// Helper function to query ClickHouse
function queryClickHouse(query, callback) {
    const cmd = `curl -s "http://panda:pandapass@localhost:18123/?query=${encodeURIComponent(query)}"`;
    exec(cmd, (error, stdout, stderr) => {
        if (error) {
            callback(error, null);
            return;
        }
        callback(null, stdout);
    });
}

// Helper function to format JSON response
function formatJSONResponse(csvData, headers) {
    const lines = csvData.trim().split('\n');
    const result = lines.map(line => {
        const values = line.split('\t');
        const obj = {};
        headers.forEach((header, index) => {
            obj[header] = isNaN(values[index]) ? values[index] : Number(values[index]);
        });
        return obj;
    });
    return result;
}

const server = http.createServer((req, res) => {
    // Set CORS headers
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Content-Type', 'application/json');

    const url = req.url;

    if (url === '/top-products') {
        const query = `SELECT productId, viewCount, cartCount, purchaseCount, totalRevenue, lastUpdated FROM local.TopProductMetrics ORDER BY totalRevenue DESC, purchaseCount DESC LIMIT 50`;

        queryClickHouse(query, (error, data) => {
            if (error) {
                res.statusCode = 500;
                res.end(JSON.stringify({ error: 'Database query failed' }));
                return;
            }

            const headers = ['productId', 'viewCount', 'cartCount', 'purchaseCount', 'totalRevenue', 'lastUpdated'];
            const jsonData = formatJSONResponse(data, headers);
            res.end(JSON.stringify(jsonData, null, 2));
        });
    }
    else if (url === '/conversion-funnel') {
        const query = `
            SELECT
                step,
                uniqueUsers,
                totalEvents,
                round(uniqueUsers * 100.0 / (SELECT uniqueUsers FROM local.ConversionFunnelMetrics WHERE step = 'view'), 2) as conversionRate,
                lastUpdated
            FROM local.ConversionFunnelMetrics
            ORDER BY CASE step WHEN 'view' THEN 1 WHEN 'cart' THEN 2 WHEN 'purchase' THEN 3 ELSE 4 END
        `;

        queryClickHouse(query, (error, data) => {
            if (error) {
                res.statusCode = 500;
                res.end(JSON.stringify({ error: 'Database query failed' }));
                return;
            }

            const headers = ['step', 'uniqueUsers', 'totalEvents', 'conversionRate', 'lastUpdated'];
            const jsonData = formatJSONResponse(data, headers);
            res.end(JSON.stringify(jsonData, null, 2));
        });
    }
    else if (url === '/hourly-activity') {
        // Since we don't have HourlyActivityMetrics, let's simulate with sample data
        const sampleData = [
            { hour: '2026-01-15 09:00:00', eventType: 'view', eventCount: 12, uniqueUsers: 8 },
            { hour: '2026-01-15 09:00:00', eventType: 'cart', eventCount: 5, uniqueUsers: 4 },
            { hour: '2026-01-15 09:00:00', eventType: 'purchase', eventCount: 2, uniqueUsers: 2 },
            { hour: '2026-01-15 10:00:00', eventType: 'view', eventCount: 15, uniqueUsers: 10 },
            { hour: '2026-01-15 10:00:00', eventType: 'cart', eventCount: 8, uniqueUsers: 6 },
            { hour: '2026-01-15 10:00:00', eventType: 'purchase', eventCount: 4, uniqueUsers: 3 }
        ];
        res.end(JSON.stringify(sampleData, null, 2));
    }
    else if (url === '/') {
        // Health check / status
        const status = {
            status: 'healthy',
            endpoints: [
                'GET /top-products',
                'GET /conversion-funnel',
                'GET /hourly-activity'
            ],
            timestamp: new Date().toISOString()
        };
        res.end(JSON.stringify(status, null, 2));
    }
    else {
        res.statusCode = 404;
        res.end(JSON.stringify({ error: 'Not Found' }));
    }
});

server.listen(PORT, () => {
    console.log(`Analytics API server running on http://localhost:${PORT}`);
    console.log('Available endpoints:');
    console.log('  GET /top-products - Top products by revenue and purchases');
    console.log('  GET /conversion-funnel - Conversion funnel metrics');
    console.log('  GET /hourly-activity - Hourly activity breakdown');
});

